using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;
class Prep{static void Main(string[] a){using(var src=new Bitmap(a[0])){int l=src.Width,t=src.Height,r=0,b=0;for(int y=0;y<src.Height;y++)for(int x=0;x<src.Width;x++)if(src.GetPixel(x,y).A>127){l=Math.Min(l,x);t=Math.Min(t,y);r=Math.Max(r,x);b=Math.Max(b,y);}int h=64,w=(int)Math.Round((r-l+1)*64.0/(b-t+1));using(var dst=new Bitmap(w,h,PixelFormat.Format32bppArgb)){for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=src.GetPixel(l+(int)((x+.5)*(r-l+1)/w),t+(int)((y+.5)*(b-t+1)/h));dst.SetPixel(x,y,c.A<128?Color.Transparent:Color.FromArgb(255,(c.R/16)*16,(c.G/16)*16,(c.B/16)*16));}dst.Save(a[1]);Console.WriteLine(w+"x"+h);using(var preview=new Bitmap(w*8,h*8)){using(var g=Graphics.FromImage(preview)){g.Clear(Color.FromArgb(131,113,81));g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.NearestNeighbor;g.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.Half;g.DrawImage(dst,0,0,w*8,h*8);}preview.Save(a[2]);}}}}}
